{
  "weft": "0.1",
  "root": {
    "kind": "screen",
    "id": "login",
    "props": {
      "label": "Sign in"
    },
    "children": [
      {
        "kind": "form",
        "id": "f1",
        "props": {
          "state": "idle"
        },
        "on": {
          "submit": "auth.submit"
        },
        "slots": {
          "footer": [
            {
              "kind": "link",
              "id": "reset",
              "on": {
                "press": "nav.reset"
              },
              "children": [
                "Forgot password?"
              ]
