              "label": "Email",
              "required": true,
              "type": "email",
              "value": {
                "bind": "$.email"
              }
            }
          },
          {
            "kind": "button",
            "id": "go",
            "props": {
              "disabled": {
                "bind": "$.email",
                "not": true
              },
              "submit": true,
              "variant": "primary"
            },
            "children": [
              "Sign in"
            ]
          }
        ]
      }
    ]
  }
}

